const trigger = $('When chat message received').first().json || {};
const question = String(trigger.chatInput || trigger.body?.chatInput || '');
const explicitArticle = question.match(/\bart[ií]culo\s+(?:n[.º°]?\s*)?(\d+)\b/i);
const articleFollowUp = question.match(/(?:^\s*[¿¡]?\s*(?:y\s+)?el\s+|\b(?:y|qué dice|que dice|decime|dime)\s+el\s+)(\d+)\b(?:\s+(?:de|del)\s+(?:la\s+)?(?:constituci[oó]n(?:\s+nacional)?|c[oó]digo\s+penal))?\s*[?!.¿¡]*\s*$/i);
const requested = explicitArticle || articleFollowUp;
if (!requested) return [{ json: { ...trigger, isExactArticle: false } }];

const response = $input.first().json || {};
const points = response.result?.points || [];
const records = new Map();
for (const point of points) {
  const payload = point.payload || {};
  const metadata = payload.metadata || {};
  const text = String(payload.text || payload.content || payload.pageContent || '');
  if (!text) continue;
  const rawSource = String(payload.source || metadata.source || 'Documento');
  const fileInfo = metadata.pdf?.info || {};
  const docKey = rawSource !== 'blob'
    ? rawSource
    : `blob:${fileInfo.CreationDate || fileInfo.Title || metadata.pdf?.totalPages || 'documento'}`;
  const source = rawSource === 'blob' ? String(fileInfo.Title || 'Documento') : rawSource;
  const page = Number(payload.page || metadata.page || metadata.loc?.pageNumber || metadata.pdf?.pageNumber || 0);
  const chunk = Number(payload.chunk_index ?? metadata.chunk_index ?? metadata.loc?.lines?.from ?? 0);
  const key = `${docKey}|${page}|${chunk}|${text}`;
  records.set(key, { docKey, source, page, chunk, text });
}

const ordered = [...records.values()].sort((a, b) =>
  a.docKey.localeCompare(b.docKey) || a.page - b.page || a.chunk - b.chunk
);
const target = new RegExp(`\\bART[IÍ]CULO\\s+${requested[1]}\\s*(?:[º°o])?\\s*[.\\-—–:]`, 'i');
function findNextDifferentArticle(text) {
  const headings = /\bART[IÍ]CULO\s+(\d+)\s*(?:[º°o])?\s*[.\-—–:]/ig;
  let match;
  while ((match = headings.exec(text))) {
    if (match[1] !== requested[1]) return match;
  }
  return null;
}
function trimRepeatedOverlap(previous, next) {
  const max = Math.min(400, previous.length, next.length);
  for (let size = max; size >= 10; size--) {
    const suffix = previous.slice(-size);
    const position = next.indexOf(suffix);
    if (position >= 0) return next.slice(position + size);
  }
  return next;
}
function appendChunk(previous, next) {
  const max = Math.min(400, previous.length, next.length);
  for (let size = max; size > 0; size--) {
    if (previous.slice(-size) === next.slice(0, size)) return next.slice(size);
  }
  return next;
}

for (let i = 0; i < ordered.length; i++) {
  const current = ordered[i];
  const found = target.exec(current.text);
  if (!found) continue;
  let first = current.text.slice(found.index);
  const firstNext = findNextDifferentArticle(first.slice(found[0].length));
  let stopped = Boolean(firstNext);
  if (firstNext) first = first.slice(0, found[0].length + firstNext.index);
  let fullText = first.trim();
  const pages = new Set(current.page ? [current.page] : []);
  for (let j = i + 1; j < ordered.length && !stopped && fullText.length < 16000; j++) {
    const next = ordered[j];
    if (next.docKey !== current.docKey) break;
    let fragmentText = next.text;
    const repeatedTarget = target.exec(fragmentText);
    if (repeatedTarget && fragmentText.slice(0, repeatedTarget.index).trim() === '') {
      fragmentText = fragmentText.slice(repeatedTarget.index + repeatedTarget[0].length);
      fragmentText = trimRepeatedOverlap(fullText, fragmentText);
    }
    const nextHeading = findNextDifferentArticle(fragmentText);
    const fragment = nextHeading
      ? fragmentText.slice(0, nextHeading.index).trim()
      : fragmentText.trim();
    if (fragment) fullText += appendChunk(fullText, `\n\n${fragment}`);
    if (next.page) pages.add(next.page);
    if (nextHeading) stopped = true;
  }
  const pageList = [...pages].sort((a, b) => a - b);
  const pageLabel = pageList.length === 1
    ? `página ${pageList[0]}`
    : pageList.length > 1 ? `páginas ${pageList[0]}–${pageList[pageList.length - 1]}` : '';
  return [{ json: {
    ...trigger,
    isExactArticle: true,
    output: `${fullText}${pageLabel ? `\n\n[Fuente: ${current.source}, ${pageLabel}]` : `\n\n[Fuente: ${current.source}]`}`,
  } }];
}
return [{ json: { ...trigger, isExactArticle: false } }];
